function metaPayload(int $class,int $method,string $args):string{return pack('nnn',$class,$method,0).$args;}
function metaDeclare(string $name,int $bits=2,array $args=[]):string{return metaPayload(50,10,Codec::shortstr($name).chr($bits).Codec::writeTable(array_map(fn($k,$v)=>[$k,$v],array_keys($args),array_values($args))));}
function metaError(string $label,callable $fn,int $code):void{try{$fn();Harness::ok($label,false);}catch(RuntimeException $e){Harness::eq($label,$code,$e->getCode());}}
