try {
    $b->saveTopology();$before=$b->raftState('meta');$bytes=file_get_contents($dir.'/topology.json');$state=Metadata::amqp($b,91,1,50,10,metaDeclare('q',2,['x-queue-type'=>'quorum']),'admin');
    Harness::eq('queue declaration stages canonical kind','queue',$state['commands'][0]['kind']);Harness::eq('queue declaration carries raw arguments','quorum',$state['commands'][0]['data']['args']['x-queue-type']);Harness::eq('staging does not create queue',false,isset($b->queues['q']));Harness::eq('staging leaves topology file untouched',$bytes,file_get_contents($dir.'/topology.json'));Harness::eq('staging leaves metadata unchanged',$before,$b->raftState('meta'));
