    $again=Metadata::amqp($b,91,1,50,10,metaDeclare('q',2,['x-queue-type'=>'quorum']),'admin');Harness::eq('equivalent declare does not propose mutation',[],$again['commands']);
    metaError('inequivalent durability rejected before proposal',fn()=>Metadata::amqp($b,91,1,50,10,metaDeclare('q',0,['x-queue-type'=>'quorum']),'admin'),406);
    metaError('inequivalent queue arguments rejected',fn()=>Metadata::amqp($b,91,1,50,10,metaDeclare('q',2,['x-queue-type'=>'stream']),'admin'),406);
    metaError('non-durable quorum rejected',fn()=>Metadata::amqp($b,91,1,50,10,metaDeclare('bad',0,['x-queue-type'=>'quorum']),'admin'),406);
    metaError('negative TTL rejected',fn()=>Metadata::amqp($b,91,1,50,10,metaDeclare('bad',2,['x-message-ttl'=>-1]),'admin'),406);
    metaError('invalid leader locator rejected',fn()=>Metadata::amqp($b,91,1,50,10,metaDeclare('bad',2,['x-queue-leader-locator'=>'none']),'admin'),406);
    Harness::eq('passive declaration uses existing read path',null,Metadata::amqp($b,91,1,50,10,metaDeclare('q',3),'admin'));Harness::eq('exclusive declaration stays local',null,Metadata::amqp($b,91,1,50,10,metaDeclare('exclusive',6),'admin'));
    $generated=Metadata::amqp($b,91,1,50,10,metaDeclare(''),'admin');Harness::ok('anonymous name generated before commit',str_starts_with($generated['name'],'amq.gen-'));Harness::eq('generated name shared with committed row',$generated['name'],$generated['commands'][0]['data']['name']);
    Harness::eq('nowait suppresses response','',Metadata::amqp($b,91,1,50,10,metaDeclare('nowait',18),'admin')['response']);
    $b->putUser('reader','password1234',[]);$b->setPermissions('reader','/','^allowed$','^q$','^events$');metaError('permission failure stages no declaration',fn()=>Metadata::amqp($b,91,1,50,10,metaDeclare('denied'),'reader'),403);Harness::eq('denied queue remains absent',false,isset($b->queues['denied']));
    $b->declareExchange('events','topic');$b->topicPermissions['reader']['/']['events']=['write'=>'^private$','read'=>'^public$'];
    $bind=fn($key)=>metaPayload(50,20,Codec::shortstr('q').Codec::shortstr('events').Codec::shortstr($key).chr(0).Codec::writeTable([]));
    $binding=Metadata::amqp($b,91,1,50,20,$bind('public'),'reader');Harness::eq('binding uses portable exchange name','events',$binding['commands'][0]['data']['exchange']);Harness::eq('binding uses topic read rule','public',$binding['commands'][0]['data']['routingKey']);Harness::eq('binding not installed before commit',[],$b->bindings);metaError('topic read mismatch denied before proposal',fn()=>Metadata::amqp($b,91,1,50,20,$bind('private'),'reader'),403);
    $b->applyRaft('meta','binding',$binding['commands'][0]['data'],2);$unbind=Metadata::amqp($b,91,1,50,50,metaPayload(50,50,Codec::shortstr('q').Codec::shortstr('events').Codec::shortstr('public').Codec::writeTable([])),'reader');Harness::eq('unbind staged canonical kind','unbind',$unbind['commands'][0]['kind']);Harness::eq('unbind does not mutate bindings',1,count($b->bindings));
    $exPayload=fn($name,$kind,$bits=2)=>metaPayload(40,10,Codec::shortstr($name).Codec::shortstr($kind).chr($bits).Codec::writeTable([]));$ex=Metadata::amqp($b,91,1,40,10,$exPayload('new','direct'),'admin');Harness::eq('exchange canonical kind','direct',$ex['commands'][0]['data']['kind']);Harness::eq('exchange not created before commit',false,isset($b->exchanges['new']));metaError('exchange equivalence validated',fn()=>Metadata::amqp($b,91,1,40,10,$exPayload('events','fanout'),'admin'),406);metaError('unknown exchange type rejected',fn()=>Metadata::amqp($b,91,1,40,10,$exPayload('new','typo'),'admin'),503);
