    $b->enqueueLocal('q','body','body','','',false);metaError('conditional delete refuses ready queue',fn()=>Metadata::amqp($b,91,1,50,40,metaPayload(50,40,Codec::shortstr('q').chr(2)),'admin'),406);$delete=Metadata::amqp($b,91,1,50,40,metaPayload(50,40,Codec::shortstr('q').chr(0)),'admin');Harness::eq('delete stages canonical kind','delete_queue',$delete['commands'][0]['kind']);Harness::ok('delete does not remove queue before commit',isset($b->queues['q']));
    metaError('truncated short string rejected',fn()=>Metadata::amqp($b,91,1,50,10,pack('nnn',50,10,0).chr(5).'a','admin'),501);metaError('truncated table rejected',fn()=>Metadata::amqp($b,91,1,50,10,metaPayload(50,10,Codec::shortstr('bad').chr(2).pack('N',5)),'admin'),501);metaError('nested field length overflow rejected',fn()=>Metadata::amqp($b,91,1,50,10,metaPayload(50,10,Codec::shortstr('bad').chr(2).pack('N',4).chr(1).'xS'.chr(0)),'admin'),501);
    $shortField=Codec::shortstr('x-expires').'s'.pack('n',800);$shortPayload=metaPayload(50,10,Codec::shortstr('expiry-short').chr(2).pack('N',strlen($shortField)).$shortField);
    Harness::eq('signed short field preserves x-expires=800',800,Metadata::amqp($b,91,1,50,10,$shortPayload,'admin')['commands'][0]['data']['args']['x-expires']);
    $negativeField=Codec::shortstr('x-expires').'s'.pack('n',65535);metaError('negative signed short expires rejected',fn()=>Metadata::amqp($b,91,1,50,10,metaPayload(50,10,Codec::shortstr('expiry-short').chr(2).pack('N',strlen($negativeField)).$negativeField),'admin'),406);
    Harness::eq('read method is not intercepted',null,Metadata::amqp($b,91,1,60,70,'','admin'));
    Harness::done();
} finally {foreach($b->allBrokers() as $scope)if(is_resource($scope->store->fp))fclose($scope->store->fp);$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $p)$p->isDir()?rmdir($p->getPathname()):unlink($p->getPathname());rmdir($dir);}
